import 'package:flutter/material.dart';import '../core/battle_layout_v4.dart';import '../core/combat_state_v4.dart';import '../models/battle_v4_models.dart';
class HexBoardPainterV4 extends CustomPainter{const HexBoardPainterV4({required this.geometry,required this.units,required this.terrain,required this.targetHexes,required this.telegraphHexes,required this.reachableHexes,required this.opportunityWarningHexes,required this.movementMode});final HexGeometryV4 geometry;final List<V4BattleUnit> units;final Map<HexCoord,TerrainV4> terrain;final Set<HexCoord> targetHexes,telegraphHexes,reachableHexes,opportunityWarningHexes;final bool movementMode;@override void paint(Canvas canvas,Size size){canvas.drawRRect(RRect.fromRectAndRadius(Offset.zero&size,const Radius.circular(14)),Paint()..color=const Color(0xFF343831));_terrain(canvas);_grid(canvas);_movement(canvas);_targets(canvas);_telegraphs(canvas);_footprints(canvas);}void _terrain(Canvas c){for(final e in terrain.entries){if(!e.key.isValidFor(geometry.columns,geometry.rows))continue;final color=switch(e.value){TerrainV4.cover||TerrainV4.forest=>const Color(0x334B7752),TerrainV4.water=>const Color(0x334A72A8),TerrainV4.fire=>const Color(0x335F301F),TerrainV4.block=>const Color(0x88505056),_=>const Color(0)};c.drawPath(geometry.path(e.key,inset:1),Paint()..color=color);}}void _grid(Canvas c){final p=Paint()..style=PaintingStyle.stroke..strokeWidth=1..color=const Color(0x445E665C);for(var x=0;x<geometry.columns;x++)for(var y=0;y<geometry.rows;y++)c.drawPath(geometry.path(HexCoord(x,y)),p);}void _movement(Canvas c){if(!movementMode)return;final f=Paint()..color=const Color(0x335CA8E8),s=Paint()..style=PaintingStyle.stroke..strokeWidth=2..color=const Color(0xFF69AEE9);for(final h in reachableHexes){final p=geometry.path(h,inset:2);c.drawPath(p,f);c.drawPath(p,s);if(opportunityWarningHexes.contains(h))_warning(c,geometry.center(h));}}void _targets(Canvas c){final f=Paint()..color=const Color(0x55E16D3C),s=Paint()..style=PaintingStyle.stroke..strokeWidth=2..color=const Color(0xFFE79159);for(final h in targetHexes){if(!h.isValidFor(geometry.columns,geometry.rows))continue;final p=geometry.path(h,inset:1);c.drawPath(p,f);c.drawPath(p,s);}}void _telegraphs(Canvas c){final f=Paint()..color=const Color(0x44FFB13B),s=Paint()..style=PaintingStyle.stroke..strokeWidth=3..color=const Color(0xFFFFC44F);for(final h in telegraphHexes){final p=geometry.path(h,inset:2);c.drawPath(p,f);c.drawPath(p,s);_warning(c,geometry.center(h));}}void _footprints(Canvas c){final p=Paint()..style=PaintingStyle.stroke..strokeWidth=2..color=const Color(0xAAE3BD58);for(final u in units.where((u)=>u.size!=V4UnitSize.normal))for(final h in u.occupied)c.drawPath(geometry.path(h,inset:1.5),p);}void _warning(Canvas c,Offset center){final tp=TextPainter(text:const TextSpan(text:'!',style:TextStyle(fontSize:13,fontWeight:FontWeight.bold,color:Colors.white)),textDirection:TextDirection.ltr)..layout();c.drawOval(Rect.fromCenter(center:center,width:18,height:18),Paint()..color=const Color(0xFFD95B4E));tp.paint(c,center-Offset(tp.width/2,tp.height/2));}@override bool shouldRepaint(covariant HexBoardPainterV4 o)=>o.units!=units||o.terrain!=terrain||o.targetHexes!=targetHexes||o.telegraphHexes!=telegraphHexes||o.reachableHexes!=reachableHexes||o.opportunityWarningHexes!=opportunityWarningHexes||o.movementMode!=movementMode;}
